import{_ as s,o as t,c as a,ah as r}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Présences et absences","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/vie-scolaire/presences-et-absences.md","filePath":"src/guide/vie-scolaire/presences-et-absences.md"}'),i={name:"guide/vie-scolaire/presences-et-absences.md"};function n(o,e,l,u,c,d){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="presences-et-absences" tabindex="-1">Présences et absences <a class="header-anchor" href="#presences-et-absences" aria-label="Permalink to &quot;Présences et absences&quot;">​</a></h1><p>Cette page couvre l&#39;appel quotidien des classes et le traitement des justificatifs d&#39;absence ou de retard soumis par les familles depuis leur espace parent.</p><h2 id="faire-l-appel-quotidien" tabindex="-1">Faire l&#39;appel quotidien <a class="header-anchor" href="#faire-l-appel-quotidien" aria-label="Permalink to &quot;Faire l&#39;appel quotidien&quot;">​</a></h2><ol><li>Ouvrez <strong>Vie scolaire → Présences</strong>. La liste affiche toutes vos classes, avec un badge <strong>Appel du jour</strong> indiquant combien d&#39;élèves ont déjà été pointés sur le total inscrit (par exemple « 18/24 fait »).</li><li>Cliquez sur <strong>Faire l&#39;appel</strong> sur la ligne de la classe concernée.</li><li>Par défaut, la page affiche le jour en cours ; changez la date en haut de page si vous devez compléter ou corriger l&#39;appel d&#39;un autre jour.</li><li>Pour chaque élève, réglez le <strong>Statut</strong> : <strong>Présent</strong>, <strong>Absent</strong> ou <strong>Retard</strong>. <ul><li>Si vous choisissez <strong>Retard</strong>, indiquez le nombre de <strong>Minutes de retard</strong>.</li><li>Cochez <strong>Justifié</strong> si l&#39;absence ou le retard est déjà couvert par un motif connu, et ajoutez une <strong>Note</strong> libre si besoin (par exemple « certificat médical fourni »).</li></ul></li><li>Cliquez sur <strong>Enregistrer</strong> — tout l&#39;appel de la classe est enregistré en une fois.</li></ol><h2 id="traiter-les-justificatifs-d-absence" tabindex="-1">Traiter les justificatifs d&#39;absence <a class="header-anchor" href="#traiter-les-justificatifs-d-absence" aria-label="Permalink to &quot;Traiter les justificatifs d&#39;absence&quot;">​</a></h2><p>Les familles soumettent leurs justificatifs d&#39;absence ou de retard depuis leur espace parent ; ils apparaissent dans <strong>Vie scolaire → Justifications d&#39;absence</strong> avec le statut <strong>En attente</strong>.</p><ol><li>Ouvrez <strong>Justifications d&#39;absence</strong>. La liste affiche, pour chaque demande, l&#39;élève, sa classe, la date concernée, le motif indiqué et son statut. Cliquez sur une ligne pour ouvrir le détail.</li><li>Si un document a été joint, téléchargez-le via <strong>Télécharger le document</strong> pour le vérifier avant de statuer.</li><li>Sur une demande <strong>en attente</strong>, choisissez : <ul><li><strong>Approuver</strong> — la justification est validée immédiatement, sans saisie supplémentaire ;</li><li><strong>Rejeter</strong> — une boîte de dialogue vous demande de saisir un <strong>Motif du rejet</strong>, obligatoire, avant de confirmer.</li></ul></li></ol><p>Une fois traitée, la demande passe au statut <strong>Approuvée</strong> ou <strong>Rejetée</strong> ; un justificatif rejeté affiche son motif de rejet directement dans la liste.</p>',8)])])}const f=s(i,[["render",n]]);export{g as __pageData,f as default};
